/* SteelFlow v0.4 — human-first, API-connected material operations console.
   No framework or CDN dependency. Backend remains the source of truth.
   Auth token is deliberately in-memory only; re-login after refresh. */
(() => {
  'use strict';
  const root = document.getElementById('root');
  const state = {token:null, name:'', role:'', username:'', page:'home', data:{}, error:'', notice:'', filter:'all', factoryFilter:'all', loading:false, synced:null};
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const kg = x => x == null ? '—' : Number(x).toLocaleString('en-IN',{maximumFractionDigits:3}) + ' kg';
  const tonnes = x => Number(x||0).toLocaleString('en-IN',{maximumFractionDigits:2}) + ' t';
  const delta = x => x == null ? '—' : `${Number(x)>0?'+':''}${kg(x)}`;
  const friendlyDate = iso => iso ? new Date(iso).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '—';
  const paths = {
    home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    warehouse:'<path d="m3 10 9-7 9 7v11H3zM8 21v-9h8v9M3 10h18"/>',
    truck:'<path d="M3 7h11v11H3zM14 11h4l3 4v3h-7M7 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4"/>',
    shield:'<path d="m12 22 0 0c-6-3-8-7-8-13V5l8-3 8 3v4c0 6-2 10-8 13Z"/><path d="m9 12 2 2 4-4"/>',
    alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 4h.01"/>',
    history:'<path d="M3 12a9 9 0 1 0 3-7M3 3v5h5M12 7v5l3 2"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    refresh:'<path d="M20 11a8 8 0 1 0-2 6M20 4v7h-7"/>',
    logout:'<path d="M10 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h5M13 7l5 5-5 5m5-5H9"/>',
    check:'<path d="m5 12 5 5L20 7"/>',
    package:'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7zM3 7l9 4 9-4M12 11v10"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 3"/>',
    activity:'<path d="M2 12h4l3-7 5 14 3-7h5"/>',
    users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M21 21v-3a5 5 0 0 0-4-5"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
    close:'<path d="M18 6 6 18M6 6l12 12"/>',
    download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
    filter:'<path d="M4 7h16M7 12h10m-7 5h4"/>',
    clipboard:'<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 5V3h6v2M9 11h6M9 15h6"/>',
    lock:'<rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/>',
    layers:'<path d="m2 9 10-6 10 6-10 6-10-6Zm0 5 10 6 10-6"/>',
  };
  const ico = (name,size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.package}</svg>`;
  const statuses = {AWAITING_INSPECTION:['Waiting for review','amber'],RELEASED:['Approved','green'],HELD:['On hold','amber'],REJECTED:['Rejected','red'],RESERVED:['Reserved','blue'],DISPATCHED:['In transit','amber'],RECEIVED_BALANCED:['Received · matched','green'],RECEIVED_WITH_DIFFERENCE:['Difference detected','red'],OPEN:['Needs investigation','red'],IN_REVIEW:['Under investigation','blue'],CLOSED_ADJUSTED:['Accounting adjusted','green'],RECORDS_CONSISTENT:['Ledger matches stock','green'],RECORDS_REQUIRE_REVIEW:['Ledger needs review','red']};
  const pill = s => { const [label,color] = statuses[s]||[String(s||'Unknown'),'gray']; return `<span class="status-pill ${color}"><span class="status-dot"></span>${esc(label)}</span>`; };
  const roles = {REFINING_OPERATOR:'Refining operator',CASTING_OPERATOR:'Casting operator',ROLLING_OPERATOR:'Rolling operator',FINISHING_OPERATOR:'Finishing operator',YARD_OPERATOR:'Yard operator',YARD_SUPERVISOR:'Yard supervisor',SMS_OPERATOR:'Melting operator',CONTROLLER:'Plant controller'};
  const menus = {
    YARD_OPERATOR:[['home','Overview','home'],['receive','Receive material','plus'],['inventory','Yard inventory','warehouse'],['transfers','Transfers','truck']],
    YARD_SUPERVISOR:[['home','Overview','home'],['review','Review & release','shield'],['inventory','Inventory','warehouse'],['reconcile','Balance checks','activity'],['activity','Activity history','history']],
    SMS_OPERATOR:[['home','Overview','home'],['transfers','Incoming transfers','truck'],['inventory','Material inventory','warehouse'],['production','Record production','activity'],['factory','Factory flow','layers']],
    REFINING_OPERATOR:[['home','Overview','home'],['production','Record production','activity'],['factory','Factory flow','layers']],
    CASTING_OPERATOR:[['home','Overview','home'],['production','Record production','activity'],['factory','Factory flow','layers']],
    ROLLING_OPERATOR:[['home','Overview','home'],['production','Record production','activity'],['factory','Factory flow','layers']],
    FINISHING_OPERATOR:[['home','Overview','home'],['production','Record production','activity'],['factory','Factory flow','layers']],
    CONTROLLER:[['home','Control center','home'],['inventory','All inventory','warehouse'],['transfers','All transfers','truck'],['alerts','Investigations','alert'],['reconcile','Balance checks','activity'],['activity','Activity history','history'],['factory','Factory flow','layers'],['production','Production runs','activity']],
  };
  function actionTitle(){return state.role==='YARD_OPERATOR'?'Receive material':state.role==='YARD_SUPERVISOR'?'Review deliveries':state.role==='CONTROLLER'?'Investigate differences':state.role==='SMS_OPERATOR'?'Confirm arrivals':'Record production';}
  function actionPage(){return state.role==='YARD_OPERATOR'?'receive':state.role==='YARD_SUPERVISOR'?'review':state.role==='CONTROLLER'?'alerts':state.role==='SMS_OPERATOR'?'transfers':'production';}
  function pageTitle(){return (menus[state.role]||[]).find(x=>x[0]===state.page)?.[1] || 'Overview';}
  function pageHeading(title,subtitle,button=''){return `<header class="page-heading"><div><div class="eyebrow">PLANT / OPERATIONS <span>/</span> CURRENT WORKSPACE</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</header>`;}
  function alertBar(){return `${state.error?`<div class="flash bad" role="alert">${ico('alert',18)}<span>${esc(state.error)}</span><button class="icon-button" aria-label="Dismiss error" data-dismiss="1">${ico('close',16)}</button></div>`:''}${state.notice?`<div class="flash good" role="status">${ico('check',18)}<span>${esc(state.notice)}</span><button class="icon-button" aria-label="Dismiss message" data-dismiss="1">${ico('close',16)}</button></div>`:''}`;}
  function field(label,id,opts={}){
    const hint=opts.hint?`<span class="field-hint">${esc(opts.hint)}</span>`:'';
    const required=opts.required===false?'':'required';
    let item='';
    if (opts.options) item=`<select id="${id}" name="${id}" ${required}>${opts.options.map(v=>`<option value="${esc(v.value)}">${esc(v.label)}</option>`).join('')}</select>`;
    else item=`<input id="${id}" name="${id}" type="${opts.type||'text'}" ${required} ${opts.min!=null?`min="${opts.min}"`:''} ${opts.max!=null?`max="${opts.max}"`:''} ${opts.step!=null?`step="${opts.step}"`:''} ${opts.readonly?'readonly':''} ${opts.value!=null?`value="${esc(opts.value)}"`:''} placeholder="${esc(opts.placeholder||'')}"/>`;
    return `<div class="form-field"><label for="${id}">${esc(label)}</label>${item}${hint}</div>`;
  }
  function loginView(){
    root.innerHTML=`<div class="login-page"><div class="login-promo"><div class="promo-orbit orbit-one"></div><div class="promo-orbit orbit-two"></div><div class="brand big"><span class="brand-mark">${ico('layers',23)}</span><span>steel<span class="teal-text">flow</span><small>MATERIAL OPERATIONS</small></span></div><div class="promo-content"><div class="promo-tag">STEELFLOW • SIX-STAGE DEMONSTRATION</div><h2>Know where every material goes.</h2><p>One shared record for deliveries, stock, handovers and differences that need attention.</p><div class="promo-steps"><span>${ico('truck',17)} Receive</span><span>${ico('check',17)} Approve</span><span>${ico('arrow',17)} Transfer</span><span>${ico('activity',17)} Trace</span></div></div><div class="promo-footer">Raw Material Six linked stages · Training environment</div></div><main class="login-area"><section class="login-box"><div class="label-upper">WELCOME BACK</div><h1>Sign in to your workspace</h1><p>Your screens and tasks will match your assigned role.</p>${alertBar()}<form id="login-form">${field('Choose your role','username',{options:[{value:'yard',label:'Yard Operator'},{value:'supervisor',label:'Yard Supervisor'},{value:'melting',label:'Melting Operator'},{value:'refining',label:'Refining Operator'},{value:'casting',label:'Casting Operator'},{value:'rolling',label:'Rolling Operator'},{value:'finishing',label:'Finishing Operator'},{value:'controller',label:'Plant Controller'}]})}${field('Password','password',{type:'password',placeholder:'Enter your demo password'})}<button class="btn primary full" type="submit">Sign in ${ico('arrow',17)}</button></form><div class="login-footnote">${ico('info',17)}<span><b>Training demo only.</b> Uses example factory accounts and does not connect to industrial equipment. Credentials are in the included README.</span></div></section></main></div>`;
    root.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));const b=e.currentTarget.querySelector('[type=submit]');b.disabled=true;try{const r=await api('/api/auth/login','POST',body,true);state.token=r.access_token;state.role=r.role;state.name=r.display_name;state.username=body.username;state.page='home';state.error='';state.notice='';await load();}catch(err){state.error=err.message;loginView();}};
  }
  async function api(path,method='GET',body=null,anon=false){
    const headers={'Content-Type':'application/json'};
    if(state.token&&!anon)headers.Authorization=`Bearer ${state.token}`;
    const response=await fetch(path,{method,headers,body:body===null?null:JSON.stringify(body),cache:'no-store'});
    let data={};try{data=await response.json();}catch{}
    if(!response.ok){
      if(response.status===401&&!anon){state.token=null;state.error='Your session ended. Sign in again.';loginView();}
      const reason=Array.isArray(data.detail)?data.detail.map(e=>e.msg).join('; '):data.detail;
      throw new Error(reason||`Could not complete the request (${response.status})`);
    }
    return data;
  }
  async function load(){
    if(!state.token)return loginView();
    try{
      const [dashboard,receipts,inventory,transfers,alerts,config]=await Promise.all([
        api('/api/dashboard'),api('/api/receipts'),api('/api/inventory'),api('/api/transfers'),api('/api/discrepancies'),api('/api/config')]);
      const [production,prodSupply,prodOverview,stages]=await Promise.all([api('/api/production/runs'),api('/api/production/supply'),api('/api/production/overview'),api('/api/production/stages')]);
      state.data={dashboard,receipts,inventory,transfers,alerts,config,production,prodSupply,prodOverview,stages};
      if(['CONTROLLER','YARD_SUPERVISOR'].includes(state.role))state.data.reconciliation=await api('/api/reconciliation/overview');
      if(state.page==='activity' && ['CONTROLLER','YARD_SUPERVISOR'].includes(state.role))state.data.audit=await api('/api/audit');
      state.synced=new Date();state.error='';render();
    }catch(err){state.error=err.message;render();}
  }
  const dash=k=>state.data.dashboard?.[k]??0;
  const count=(type)=>({review:(state.data.receipts||[]).filter(x=>x.status==='AWAITING_INSPECTION').length,transfers:(state.data.transfers||[]).filter(x=>x.status==='DISPATCHED').length,alerts:(state.data.alerts||[]).filter(x=>['OPEN','IN_REVIEW'].includes(x.status)).length})[type]||0;
  const navCounter=id=>id==='review'?count('review'):id==='alerts'?count('alerts'):id==='transfers'&&state.role==='SMS_OPERATOR'?count('transfers'):0;
  function layout(body){
    const nav=menus[state.role]||menus.CONTROLLER;
    root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${ico('layers',23)}</span><span>steel<span class="teal-text">flow</span><small>MATERIAL OPERATIONS</small></span></div><div class="nav-eyebrow">WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([id,title,glyph])=>`<button type="button" data-page="${id}" class="nav-link ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${ico(glyph,18)}<span>${esc(title)}</span>${navCounter(id)?`<span class="nav-count">${navCounter(id)}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="plant-tile">${ico('warehouse',22)}<span><strong>DEMO STEELWORKS</strong><small>Yard → Finished Goods</small></span></div><span>OPERATIONS CONSOLE · V2.0</span></div></aside><div class="work-area"><div class="topbar"><div class="breadcrumb">SteelFlow <span> / </span> Material Operations <span> / </span> <strong>${esc(pageTitle())}</strong></div><div class="top-actions"><span class="environment"><span></span> Simulation data</span><button class="top-refresh" id="refresh" title="Refresh live records" aria-label="Refresh records">${ico('refresh',17)}</button><span class="avatar" title="${esc(state.name)}">${esc(state.name.split(' ').map(s=>s[0]).join('').slice(0,2).toUpperCase())}</span><div class="user-text"><strong>${esc(state.name)}</strong><small>${esc(roles[state.role]||'User')}</small></div><button class="sign-out" id="logout" title="Sign out">${ico('logout',17)}<span>Sign out</span></button></div></div><main class="page"><div class="pilot-notice">${ico('info',16)} <span><strong>Training environment.</strong> Sample production records · not connected to live plant equipment.</span></div>${alertBar()}${body}<footer class="page-footer">${ico('shield',15)} Discrepancies are measurement differences, not confirmed physical losses. ${state.synced?`<span>Updated ${state.synced.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</span>`:''}</footer></main></div></div>`;
    root.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>go(el.dataset.page));
    root.querySelector('#refresh').onclick=()=>load();
    root.querySelector('#logout').onclick=async()=>{try{await api('/api/auth/logout','POST');}catch{}state.token=null;state.name='';state.role='';state.data={};state.error='';state.notice='';loginView();};
    root.querySelectorAll('[data-dismiss]').forEach(e=>e.onclick=()=>{state.error='';state.notice='';e.closest('.flash')?.remove();});
  }
  function go(page){if(!(menus[state.role]||[]).some(x=>x[0]===page)){return;}state.page=page;state.filter='all';state.error='';state.notice='';if(page==='activity'){load();return;}render();}
  function render(){if(!state.token)return loginView();let view;
    switch(state.page){case 'receive':view=receiveView();break;case 'review':view=reviewView();break;case 'inventory':view=inventoryView();break;case 'transfers':view=transfersView();break;case 'alerts':view=alertsView();break;case 'reconcile':view=reconcileView();break;case 'activity':view=activityView();break;case 'production':view=productionView();break;case 'factory':view=factoryView();break;default:view=homeView();}
    layout(view);attach();
  }

  const stageRole={SMS_OPERATOR:'MELTING',REFINING_OPERATOR:'REFINING',CASTING_OPERATOR:'CASTING',ROLLING_OPERATOR:'ROLLING',FINISHING_OPERATOR:'FINISHING'};
  const stageNames={MELTING:'Steel Melting Shop',REFINING:'Ladle Refining',CASTING:'Continuous Casting',ROLLING:'Rolling Mill',FINISHING:'Quality & Finishing'};
  const productNames={MELTING:'Liquid steel',REFINING:'Refined liquid steel',CASTING:'Steel billets',ROLLING:'Rolled steel',FINISHING:'Finished steel'};
  function productionView(){
    const stage=stageRole[state.role];const canWrite=!!stage;
    const sources=(state.data.prodSupply||[]).filter(x=>x.stage_for===stage);
    const runs=(state.data.production||[]).filter(x=>!stage||x.stage_code===stage);
    const option=sources.map(s=>`<option value="${esc(s.source_type+'|'+s.id)}">${esc(s.label)} · ${esc(s.material)} · ${kg(s.available_kg)} available</option>`).join('');
    const form=canWrite?`<section class="panel sf-prod-form"><div class="panel-head"><div><h2>Record a production run</h2><p>${esc(stageNames[stage])} · All values in kilograms</p></div></div><div class="sf-pad"><p class="section-help">Choose real received stock or an output batch from the previous department. Every saved record is linked to its inputs.</p><form id="production-form"><div class="step-label"><span>1</span> Material being processed</div><div id="prod-input-rows"><div class="sf-line"><div class="form-field"><label>Available batch</label><select name="source" required>${option||'<option value="">No available inputs yet</option>'}</select></div><div class="form-field"><label>Quantity used (kg)</label><input name="used" type="number" min="0.001" step="0.001" required placeholder="e.g. 5000"/></div></div></div><button type="button" class="btn secondary" id="prod-add-input">+ Add another input</button><div class="form-divider"></div><div class="step-label"><span>2</span> What was produced?</div><div id="prod-output-rows"><div class="sf-line sf-output"><div class="form-field"><label>Output category</label><select name="kind"><option value="PRODUCT">Main product</option><option value="SCRAP">Scrap / reject</option><option value="BYPRODUCT">By-product</option></select></div><div class="form-field"><label>Output description</label><input name="material" required value="${esc(productNames[stage])}"/></div><div class="form-field"><label>Quantity (kg)</label><input name="amount" type="number" min="0.001" step="0.001" placeholder="e.g. 4900" required/></div></div></div><button type="button" class="btn secondary" id="prod-add-output">+ Add scrap or by-product</button><div class="sf-balance" id="prod-balance" aria-live="polite">Enter inputs and outputs to calculate the unexplained difference.</div><div class="form-divider"></div><div class="form-grid">${field('Production log / heat reference','prod-evidence',{placeholder:'e.g. HEAT-1042'})}${field('Notes (optional)','prod-notes',{required:false,placeholder:'Process observations'})}</div><button type="submit" class="btn primary">Save production record ${ico('arrow',17)}</button></form></div></section>`:'<section class="caution-banner">Controllers can inspect records and investigate unexplained balances. Only the operator assigned to a stage can enter production.</section>';
    return `${pageHeading(canWrite?'Record production':'Production records',canWrite?'Log material consumed, product and other documented streams.':'Review the production history across every manufacturing department.')}${form}<section class="panel sf-history"><div class="panel-head"><div><h2>Production history</h2><p>Saved runs are backed by the shared database</p></div><button class="btn secondary" id="prod-export">${ico('download',16)} Export CSV</button></div><div class="table-wrap"><table>${tableHeads(['Reference','Department','Inputs','Accounted outputs','Unexplained','Status','Trace'])}<tbody>${runs.map(r=>`<tr><td><strong>${esc(r.reference)}</strong><small>${friendlyDate(r.created_at)}</small></td><td>${esc(r.stage_name)}</td><td>${kg(r.input_total_kg)}</td><td>${kg(r.output_total_kg)}</td><td class="numeric">${kg(r.residual_kg)}</td><td>${r.status==='BALANCED'?pill('RELEASED'):pill(r.status==='NEEDS_REVIEW'?'OPEN':'IN_REVIEW')}</td><td><button class="btn tiny secondary" data-run="${esc(r.id)}">Details</button></td></tr>`).join('')}</tbody></table></div>${!runs.length?'<div class="empty-state">No production runs yet. Start by receiving and dispatching material to Melting.</div>':''}</section>`;
  }
  function factoryView(){
    const o=state.data.prodOverview||{};const st=o.stages||[];
    return `${pageHeading('Factory flow','Follow material from raw receiving to finished goods and locate open investigations.',`<button class="btn secondary" id="factory-export">${ico('download',16)} Export all production</button>`)}
      <div class="metric-grid">${metric('Production runs',o.total_runs||0,'Across five processing stages','activity')}${metric('Process investigations',o.open_process_cases||0,'Unexplained stage balances','alert','red')}${metric('Available finished steel',tonnes(Number(o.available_finished_kg||0)/1000),'Produced and not consumed','package')}${metric('Transfer differences',count('alerts'),'Material handover investigations','truck','amber')}</div>
      <section class="panel sf-flow"><div class="panel-head"><div><h2>Production route</h2><p>Recorded activity for the six-stage reference route</p></div><span class="small-tag">ROUTE / 06 STAGES</span></div><div class="flow-legend"><span><i class="legend-dot good"></i> No open exception</span><span><i class="legend-dot bad"></i> Needs review</span><span class="flow-tip">Scroll stages → · Select any stage to inspect records</span></div><div class="sf-flow-items"><div class="sf-stage sf-entry" role="group" aria-label="Raw Material Yard"><span class="sf-stage-head"><span class="sf-stage-number">01</span><span class="stage-label">MATERIAL INTAKE</span></span><h3>Raw Material Yard</h3><p>Receiving · stock · dispatch</p><div class="sf-stage-bottom"><strong>${(state.data.receipts||[]).filter(r=>r.status==='RELEASED').length} released receipts</strong><span class="stage-status"><i class="legend-dot good"></i> Intake</span></div></div>${st.map((s,i)=>`<button type="button" class="sf-stage ${s.open_cases?'sf-warning':''}" data-stage-select="${esc(s.code)}" aria-label="Inspect ${esc(s.name)}"><span class="sf-stage-head"><span class="sf-stage-number">0${i+2}</span><span class="stage-label">PROCESS ${String(i+1).padStart(2,'0')}</span></span><h3>${esc(s.name)}</h3><p>${esc(s.runs)} production runs</p><div class="sf-stage-bottom"><strong>${kg(s.output_kg)} output</strong><span class="stage-status ${s.open_cases?'issue':''}"><i class="legend-dot ${s.open_cases?'bad':'good'}"></i>${s.open_cases?`${s.open_cases} open`:'Balanced'}</span></div></button>`).join('')}</div></section>
      <section class="panel sf-history"><div class="panel-head"><div><h2>Recent production</h2><p>Each saved run preserves source batches and output quantities</p></div><div class="factory-filters" role="group" aria-label="Filter production records"><button type="button" class="factory-filter ${state.factoryFilter==='all'?'selected':''}" data-factory-filter="all" aria-pressed="${state.factoryFilter==='all'}">All runs</button><button type="button" class="factory-filter ${state.factoryFilter==='issues'?'selected':''}" data-factory-filter="issues" aria-pressed="${state.factoryFilter==='issues'}">Needs review <span>${(state.data.production||[]).filter(r=>r.status==='NEEDS_REVIEW').length}</span></button></div></div>${(state.data.production||[]).filter(r=>state.factoryFilter==='all'||r.status==='NEEDS_REVIEW').slice(0,20).map(r=>`<div class="sf-runrow"><div><b>${esc(r.reference)}</b><small>${esc(r.stage_name)} · ${friendlyDate(r.created_at)}</small></div><div><b>${kg(r.input_total_kg)} input</b><small>${kg(r.residual_kg)} unexplained</small></div><button class="btn tiny secondary" data-run="${esc(r.id)}">Open record</button></div>`).join('')||'<div class="empty-state">No manufacturing runs have been recorded yet.</div>'}</section>`;
  }
  function runDetails(id){const r=(state.data.production||[]).find(v=>v.id===id);if(!r)return;
    const ins=r.inputs.map(i=>detail(i.source_label+' · '+i.material,kg(i.amount_kg))).join('');
    const outs=r.outputs.map(o=>`<div class="detail-row"><span>${esc(o.kind)} · ${esc(o.batch_no)} · ${esc(o.material)}</span><strong>${kg(o.initial_kg)} ${o.kind==='PRODUCT'?`<button class="btn tiny secondary" data-genealogy="${esc(o.id)}">Trace</button>`:''}</strong></div>`).join('');
    readModal(r.reference,`${detail('Department',r.stage_name)}${detail('Recorded by',r.operator)}${detail('Production evidence',r.evidence_reference)}<h3 class="modal-subheading">Material used</h3>${ins}<h3 class="modal-subheading">Outputs</h3>${outs}${detail('Unexplained balance',kg(r.residual_kg))}<div class="explain-mini">Balance differences are not automatically classified as material losses. The system cannot establish the root cause without investigation.</div>${state.role==='CONTROLLER'&&r.status==='NEEDS_REVIEW'?`<button class="btn primary" id="review-process" data-run-id="${esc(r.id)}">Start investigation</button>`:''}`);
    root.querySelectorAll('[data-genealogy]').forEach(b=>b.onclick=()=>showGenealogy(b.dataset.genealogy));
    root.querySelector('#review-process')?.addEventListener('click',()=>{root.querySelector('.modal-overlay')?.remove();actionModal({title:'Investigate a production balance',description:'Record what needs verification. The original process records will remain unchanged.',fields:[{id:'evidence_reference',label:'Investigation reference',minlength:3},{id:'note',label:'Evidence and investigation notes',type:'textarea',minlength:15}],submitText:'Save investigation',onSubmit:v=>act(`/api/production/runs/${encodeURIComponent(r.id)}/review`,'POST',v,'Production investigation recorded; original measurements preserved.')});});
  }
  async function showGenealogy(batch){try{const g=await api('/api/production/genealogy/'+encodeURIComponent(batch));readModal('Trace batch '+g.batch_no,`<div class="explain-mini">This is batch ancestry (which recorded batches contributed), not chemical/atomic provenance.</div><h3 class="modal-subheading">Upstream material history</h3>${g.nodes.map(n=>`<div class="detail-row"><span>${esc(n.stage)} · ${esc(n.label)}</span><strong>${kg(n.amount_kg)}</strong></div>`).join('')}`);}catch(err){state.error=err.message;render();}}
  function prodCsv(){const rows=[['Run','Stage','Date','Input kg','Accounted output kg','Unexplained kg','Status','Reference'],...(state.data.production||[]).map(r=>[r.reference,r.stage_code,r.created_at,r.input_total_kg,r.output_total_kg,r.residual_kg,r.status,r.evidence_reference])];const safe=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=rows.map(row=>row.map(safe).join(',')).join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='SteelFlow_Production.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function attachProduction(){
    root.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>runDetails(b.dataset.run));
    root.querySelectorAll('[data-stage-select]').forEach(b=>b.onclick=()=>{const rows=(state.data.production||[]).filter(r=>r.stage_code===b.dataset.stageSelect);readModal(stageNames[b.dataset.stageSelect],rows.map(r=>`<div class="detail-row"><span>${esc(r.reference)} · ${esc(r.status)}</span><strong>${kg(r.residual_kg)} unexplained</strong></div>`).join('')||'No production runs at this stage yet.');});
    root.querySelector('#prod-export')?.addEventListener('click',prodCsv);root.querySelector('#factory-export')?.addEventListener('click',prodCsv);
    const f=root.querySelector('#production-form');if(!f)return;
    const sourceRow=f.querySelector('.sf-line').outerHTML;
    f.querySelector('#prod-add-input').onclick=()=>{const holder=f.querySelector('#prod-input-rows');holder.insertAdjacentHTML('beforeend',sourceRow);update();};
    f.querySelector('#prod-add-output').onclick=()=>{f.querySelector('#prod-output-rows').insertAdjacentHTML('beforeend',`<div class="sf-line sf-output"><div class="form-field"><label>Output category</label><select name="kind"><option value="SCRAP">Scrap / reject</option><option value="BYPRODUCT">By-product</option><option value="PRODUCT">Main product</option></select></div><div class="form-field"><label>Material / stream</label><input name="material" required placeholder="e.g. Steel slag"/></div><div class="form-field"><label>Quantity (kg)</label><input name="amount" type="number" min="0.001" step="0.001" required/></div><button type="button" class="btn tiny secondary sf-remove">Remove</button></div>`);update();};
    f.addEventListener('click',e=>{if(e.target.closest('.sf-remove')){e.target.closest('.sf-output').remove();update();}});
    const update=()=>{const sum=sel=>[...f.querySelectorAll(sel)].reduce((a,n)=>a+(Number(n.value)||0),0);const a=sum('#prod-input-rows input[name="used"]'),b=sum('#prod-output-rows input[name="amount"]');f.querySelector('#prod-balance').textContent=`Inputs ${kg(a)} − documented outputs ${kg(b)} = ${kg(a-b)} unexplained · ${a>=b?'Review any remaining difference':'Output exceeds input: add other input materials or correct values'}`;};f.addEventListener('input',update);
    f.onsubmit=async e=>{e.preventDefault();const ins=[...f.querySelectorAll('#prod-input-rows .sf-line')].map(row=>{const [source_type,source_id]=row.querySelector('select[name="source"]').value.split('|');return {source_type,source_id,amount_kg:row.querySelector('input[name="used"]').value};});const outs=[...f.querySelectorAll('#prod-output-rows .sf-output')].map(row=>({kind:row.querySelector('select[name="kind"]').value,material:row.querySelector('input[name="material"]').value,amount_kg:row.querySelector('input[name="amount"]').value}));if(ins.some(x=>!x.source_id)){state.error='No material is available for this stage. Complete the upstream stage first.';render();return;}await act('/api/production/runs','POST',{stage_code:stageRole[state.role],inputs:ins,outputs:outs,evidence_reference:f.querySelector('#prod-evidence').value,notes:f.querySelector('#prod-notes').value},'Production saved. Check the output batches or factory flow to trace the result.');};update();
  }

  const metric=(title,value,sub,glyph,color='teal')=>`<section class="metric-card"><div class="metric-top"><span>${esc(title)}</span><div class="metric-icon ${color}">${ico(glyph,20)}</div></div><strong class="metric-value">${esc(value)}</strong><small>${esc(sub)}</small></section>`;
  function homeView(){
    const available=(state.data.inventory||[]).filter(x=>x.location_kind==='YARD').reduce((acc,x)=>acc+Number(x.available_kg),0);
    const intransit=Number(dash('transit_balance_kg'));
    const open=(state.data.alerts||[]).filter(x=>['OPEN','IN_REVIEW'].includes(x.status)).length,waiting=count('review'),enroute=count('transfers');
    const actions=[{title:'Material awaiting inspection',n:waiting,description:'Supervisor approval is needed before it can be dispatched.',page:'review',icon:'clipboard',role:'YARD_SUPERVISOR'},
      {title:'Transfers awaiting receipt',n:enroute,description:'Incoming material needs confirmation at the melting shop.',page:'transfers',icon:'truck',role:'SMS_OPERATOR'},
      {title:'Differences need investigation',n:open,description:'Compare sending and receiving measurements before deciding what happened.',page:'alerts',icon:'alert',role:'CONTROLLER'}];
    const primary=actions.find(x=>x.role===state.role)||{title:'Record a material delivery',page:'receive',icon:'plus'};
    const transfers=(state.data.transfers||[]).slice(0,4);
    return `${pageHeading(state.role==='CONTROLLER'?'Plant control center':'Today’s workspace',state.role==='CONTROLLER'?'Your material operations at a glance. Review exceptions before they become delays.':'Your starting point for deliveries, stock and movements that need attention.',`<button class="btn subtle" id="export-summary">${ico('download',17)} Export summary</button>`)}
      <section class="hero"><div class="hero-copy"><div class="hero-kicker"><span class="live-indicator"></span> OPERATIONS DESK <span class="hero-divider">/</span> TRAINING ENVIRONMENT</div><h2>Material operations, under control.</h2><p>One place to review handovers, find inventory, and act on exceptions.</p></div><button class="hero-action" data-go="${actionPage()}">${ico('plus',18)} ${esc(actionTitle())} ${ico('arrow',17)}</button></section>
      <div class="metric-grid">${metric('Available yard stock',tonnes(available/1000),'Approved, unreserved material','warehouse')}${metric('Awaiting inspection',waiting,'Waiting for supervisor review','clipboard','amber')}${metric('Material in transit',tonnes(intransit/1000),'Includes unresolved differences','truck','blue')}${metric('Open discrepancies',open,'Controller attention needed','alert','red')}</div>
      <div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Priority tasks</h2><p>Take the next action to keep material moving</p></div></div><div class="task-list">${actions.map(a=>`<div class="task"><div class="task-icon ${a.n && a.page==='alerts'?'red':a.page==='review'?'amber':'blue'}">${ico(a.icon,19)}</div><div><strong>${a.n} ${esc(a.title.toLowerCase())}</strong><small>${esc(a.description)}</small></div>${(menus[state.role]||[]).some(x=>x[0]===a.page)?`<button class="btn tiny secondary" data-go="${a.page}">View ${ico('arrow',14)}</button>`:'<span class="task-owner">Assigned to another role</span>'}</div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Tasks you can perform with your access</p></div></div><div class="quick-actions">${(menus[state.role]||[]).filter(x=>!['home','activity'].includes(x[0])).slice(0,3).map(([id,label,glyph])=>`<button class="quick-row" data-go="${id}"><span class="quick-icon">${ico(glyph,19)}</span><span><strong>${esc(label)}</strong><small>${({receive:'Register a truck delivery',review:'Approve or hold incoming stock',inventory:'Find material and its history',transfers:'Track or confirm handovers',alerts:'Review reported weight differences',reconcile:'Check batch accounting against records'})[id]||'View records'}</small></span>${ico('chevron',17)}</button>`).join('')}</div></section></div>
      <div class="content-grid lower"><section class="panel"><div class="panel-head"><div><h2>Material handover</h2><p>All six stages use database-backed records</p></div><span class="small-tag">6 stages configured</span></div><div class="route"><div class="route-node"><div class="route-node-icon">${ico('warehouse',24)}</div><div><strong>Raw Material Yard</strong><small>Receive · review · dispatch</small></div></div><div class="route-center"><span>VERIFIED TRANSFER RECORDS</span>${ico('arrow',25)}</div><div class="route-node"><div class="route-node-icon blue">${ico('truck',24)}</div><div><strong>Melting Shop</strong><small>Confirm incoming weight</small></div></div></div><div class="explainer">${ico('info',18)}<span>Each transfer stores both departments’ own measurements. Any difference remains visible for investigation.</span></div></section>
      <section class="panel"><div class="panel-head"><div><h2>Recent transfers</h2><p>Latest movements in the shared record</p></div>${(menus[state.role]||[]).some(x=>x[0]==='transfers')?'<button class="text-action" data-go="transfers">View all →</button>':''}</div>${transfers.length?transfers.map(t=>`<div class="recent-row"><div class="recent-icon">${ico(t.status.includes('DIFFERENCE')?'alert':'truck',17)}</div><div><strong>${esc(t.transfer_no)}</strong><small>${esc(t.lot_no)} · ${kg(t.dispatched_kg??t.reserved_kg)}</small></div>${pill(t.status)}</div>`).join(''):'<div class="empty-state">No transfers yet. Create a delivery, approve it and prepare your first transfer.</div>'}</section></div>`;
  }
  function receiveView(){const mats=(state.data.config?.materials||[]).map(x=>({value:x.code,label:x.name}));return `${pageHeading('Receive material','Record an incoming truck delivery. We calculate the material weight for you.')}
    <div class="form-layout"><section class="panel form-panel"><div class="step-label"><span>1</span> Delivery details</div><p class="section-help">Use the information from the supplier’s delivery slip.</p><form id="receipt-form"><div class="form-grid">${field('Material type','material_code',{options:mats})}${field('Supplier name','supplier',{placeholder:'e.g. Eastern Scrap Traders'})}${field('Vehicle number','vehicle_number',{placeholder:'e.g. TS09AB1234'})}${field('Delivery slip / PO number','delivery_reference',{placeholder:'e.g. PO-0125'})}${field('Weighbridge ticket','weighbridge_ticket',{placeholder:'e.g. WB-1003'})}${field('Storage location','location_code',{options:[{value:'YARD-A',label:'Yard Storage A'}]})}</div>
      <div class="form-divider"></div><div class="step-label"><span>2</span> Record the weights</div><p class="section-help">Enter the loaded and empty truck weights from the weighbridge.</p><div class="form-grid">${field('Loaded truck weight (kg)','gross_kg',{type:'number',step:'0.001',min:'0.001',placeholder:'32800'})}${field('Empty truck weight (kg)','tare_kg',{type:'number',step:'0.001',min:'0',placeholder:'12800'})}</div><div class="weight-summary"><div><small>CALCULATED MATERIAL WEIGHT</small><strong id="net-display">—</strong><p>Loaded truck minus empty truck</p></div><div class="weight-symbol">${ico('package',25)}</div></div><p class="inline-error" id="weight-error" hidden>Loaded truck weight must be greater than empty truck weight.</p><div class="form-divider"></div><div class="form-submit"><div class="helper-note">${ico('shield',17)} This entry goes to the supervisor for approval. It will not become available stock yet.</div><button class="btn primary" type="submit">Submit for inspection ${ico('arrow',17)}</button></div></form></section>
      <aside class="side-stack"><section class="panel side-panel"><h3>What happens next?</h3><div class="vertical-steps"><div><b>1</b><span><strong>Submit delivery</strong><small>We save your weighing details.</small></span></div><div><b>2</b><span><strong>Supervisor reviews</strong><small>Material is approved, held or rejected.</small></span></div><div><b>3</b><span><strong>Stock becomes available</strong><small>Approved material can be sent to Melting.</small></span></div></div></section><div class="tip-box">${ico('info',20)}<div><strong>Prevent duplicate entries</strong><p>Each weighbridge ticket must be unique. If the system says a ticket exists, check previous receipts before entering it again.</p></div></div></aside></div>`;}
  function searchBar(placeholder='Search by reference, material or location'){return `<div class="search-field">${ico('search',17)}<input id="table-search" type="search" placeholder="${esc(placeholder)}" aria-label="Search records"/><span class="key-hint">Search</span></div>`;}
  function tableHeads(vals){return `<thead><tr>${vals.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead>`;}
  function reviewView(){const rows=(state.data.receipts||[]);const waiting=rows.filter(x=>x.status==='AWAITING_INSPECTION').length;return `${pageHeading('Review & release','Approve material before it can enter available inventory.')}<div class="page-stat-row"><div class="summary-card">${ico('clipboard',19)} <span><b>${waiting}</b> deliveries awaiting inspection</span></div><span class="muted-small">Review based on the actual documented inspection, not the weight alone.</span></div><section class="panel"><div class="panel-head"><div><h2>Incoming deliveries</h2><p>Supplier receipts awaiting review, plus previous decisions</p></div>${searchBar('Search ticket, supplier or material')}</div><div class="table-wrap"><table>${tableHeads(['Receipt / ticket','Material','Supplier','Net weight','Status','Next action'])}<tbody id="records-body">${rows.map(r=>`<tr data-search="${esc([r.receipt_no,r.ticket,r.material,r.supplier,r.status].join(' ').toLowerCase())}"><td><strong>${esc(r.receipt_no)}</strong><small>${esc(r.ticket)}</small></td><td>${esc(r.material)}</td><td>${esc(r.supplier)}</td><td class="numeric">${kg(r.net_kg)}</td><td>${pill(r.status)}</td><td>${['AWAITING_INSPECTION','HELD'].includes(r.status)?`<div class="table-actions"><button class="btn tiny primary" data-review="${esc(r.id)}" data-decision="RELEASED">Approve</button><button class="btn tiny secondary" data-review="${esc(r.id)}" data-decision="HELD">Hold</button><button class="btn tiny outline-red" data-review="${esc(r.id)}" data-decision="REJECTED">Reject</button></div>`:'<span class="muted-small">Decision recorded</span>'}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-state">No receipts have been recorded yet.</div>'}<div class="no-results" id="no-results" hidden>No matching receipts found.</div></section>`;}
  function inventoryView(){const rows=state.data.inventory||[],yard=rows.filter(x=>x.location_kind==='YARD');const sum=(data,key)=>data.reduce((a,b)=>a+Number(b[key]||0),0);return `${pageHeading('Material inventory','Find a lot, see its actual quantities and trace its movement.',state.role==='YARD_OPERATOR'?`<button class="btn primary" data-go="receive">${ico('plus',17)} Receive material</button>`:'')}
    <div class="inventory-cards"><div><small>YARD ON HAND</small><strong>${tonnes(sum(yard,'on_hand_kg')/1000)}</strong></div><div><small>YARD RESERVED</small><strong>${tonnes(sum(yard,'reserved_kg')/1000)}</strong></div><div><small>AVAILABLE TO SEND</small><strong>${tonnes(sum(yard,'available_kg')/1000)}</strong></div></div><section class="panel"><div class="panel-head"><div><h2>Stock by material lot</h2><p>Quantities shown are current stored database balances</p></div>${searchBar('Find lot, material or location')}</div><div class="table-wrap"><table>${tableHeads(['Lot / material','Where it is','On hand','Reserved','Available','Actions'])}<tbody id="records-body">${rows.map(r=>`<tr data-search="${esc([r.lot_no,r.material,r.location].join(' ').toLowerCase())}"><td><strong>${esc(r.lot_no)}</strong><small>${esc(r.material)}</small></td><td>${esc(r.location)}</td><td class="numeric">${kg(r.on_hand_kg)}</td><td class="numeric">${kg(r.reserved_kg)}</td><td class="numeric emphasis">${kg(r.available_kg)}</td><td><div class="table-actions"><button class="btn tiny secondary" data-lot="${esc(r.lot_id)}">${ico('history',14)} Trace lot</button>${state.role==='YARD_OPERATOR'&&r.location_kind==='YARD'&&Number(r.available_kg)>0?`<button class="btn tiny primary" data-reserve="${esc(r.lot_id)}" data-available="${esc(r.available_kg)}">Send to Melting ${ico('arrow',13)}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-state">No stock yet. Receive and approve material to create the first lot.</div>'}<div class="no-results" id="no-results" hidden>No matching material lots found.</div></section>`;}
  function transfersView(){const all=(state.data.transfers||[]),rows=state.role==='SMS_OPERATOR'?all.filter(t=>t.status==='DISPATCHED'):all;const filters=[['all','All'],['reserved','Ready to dispatch'],['transit','In transit'],['difference','Differences'],['done','Received']];return `${pageHeading(state.role==='SMS_OPERATOR'?'Incoming transfers':'Material transfers','Every handover links the sender’s record with the receiver’s independent measurement.')}
    <section class="panel"><div class="panel-head"><div><h2>${state.role==='SMS_OPERATOR'?'Waiting for your confirmation':'Transfer records'}</h2><p>${rows.length} transfer${rows.length===1?'':'s'} shown</p></div>${searchBar('Search transfer or lot')}</div>${state.role!=='SMS_OPERATOR'?`<div class="filter-tabs" role="group" aria-label="Filter transfer status">${filters.map(([id,label])=>`<button class="filter-tab ${state.filter===id?'selected':''}" data-filter="${id}" aria-pressed="${state.filter===id?'true':'false'}">${label}</button>`).join('')}</div>`:''}<div class="table-wrap"><table>${tableHeads(['Transfer / lot','Material route','Dispatched / reserved','Received','Status','Action'])}<tbody id="records-body">${rows.map(t=>`<tr data-status="${esc(t.status)}" data-search="${esc([t.transfer_no,t.lot_no,t.source,t.destination,t.status].join(' ').toLowerCase())}"><td><strong>${esc(t.transfer_no)}</strong><small>${esc(t.lot_no)}</small></td><td>${esc(t.source)}<small class="route-dest">${ico('arrow',12)} ${esc(t.destination)}</small></td><td class="numeric">${kg(t.dispatched_kg??t.reserved_kg)}</td><td class="numeric">${kg(t.received_kg)}</td><td>${pill(t.status)}</td><td><div class="table-actions">${state.role==='YARD_OPERATOR'&&t.status==='RESERVED'?`<button class="btn tiny primary" data-dispatch="${esc(t.id)}">Confirm dispatch ${ico('arrow',13)}</button>`:state.role==='SMS_OPERATOR'&&t.status==='DISPATCHED'?`<button class="btn tiny primary" data-confirm="${esc(t.id)}" data-sent="${esc(t.dispatched_kg)}">Confirm receipt ${ico('arrow',13)}</button>`:''}<button class="btn tiny secondary" data-transfer-details="${esc(t.id)}">View record</button></div></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-state">No transfers in this queue.</div>'}<div class="no-results" id="no-results" hidden>No transfers match your filters.</div></section>`;}
  function alertsView(){const rows=state.data.alerts||[];return `${pageHeading('Discrepancy investigations','Compare measurements and document what must be checked — without assuming material was lost.')}
    <div class="caution-banner">${ico('alert',20)} <span><strong>What does an alert mean?</strong> The sending and receiving weights differ. It may indicate a measurement or recording issue, not necessarily a physical loss.</span></div><section class="panel"><div class="panel-head"><div><h2>Recorded differences</h2><p>${rows.filter(r=>r.status==='OPEN').length} investigations awaiting action</p></div>${searchBar('Search transfer or investigation')}</div><div class="investigation-list" id="records-body">${rows.map(r=>`<article class="investigation-item" data-search="${esc([r.transfer_no,r.status,r.note||''].join(' ').toLowerCase())}"><div class="investigation-icon">${ico('alert',22)}</div><div class="investigation-copy"><strong>${esc(r.transfer_no)}</strong><p>${Number(r.difference_kg)>0?'Receiving record is lower than dispatch.':Number(r.difference_kg)<0?'Receiving record is higher than dispatch.':'Records match.'}</p>${r.note?`<div class="investigation-note">${ico('clipboard',15)} ${esc(r.note)}</div>`:''}</div><div class="investigation-end"><strong>${delta(r.difference_kg)}</strong>${pill(r.status)}<div class="table-actions">${r.status==='OPEN'?`<button class="btn tiny primary" data-investigate="${esc(r.id)}">Start investigation ${ico('arrow',13)}</button>` : r.status==='IN_REVIEW'&&Number(r.difference_kg)>0?`<button class="btn tiny secondary" data-close-shortage="${esc(r.id)}" data-amount="${esc(r.difference_kg)}">Approve accounting adjustment</button>`:`<span class="muted-small">${r.status==='CLOSED_ADJUSTED'?'Accounted for · case closed':'Review in progress'}</span>`}<button class="btn tiny secondary" data-view-transfer-id="${esc(r.transfer_id)}">Evidence</button></div></div></article>`).join('')}</div>${rows.length?'':'<div class="empty-state">No weight differences recorded. Matched transfers do not create investigations.</div>'}<div class="no-results" id="no-results" hidden>No matching investigations found.</div></section>`;}
  function reconcileView(){
    const data=state.data.reconciliation||{summary:{},lots:[],transfers:[]};
    const summ=data.summary||{};
    const rows=data.lots||[];
    const movements=data.transfers||[];
    return `${pageHeading('Material balance checks','Compare recorded stock against the full movement ledger, batch by batch.')}
      <div class="caution-banner">${ico('info',20)} <span><strong>What does “records consistent” mean?</strong> The recorded inventory matches the event history. It does not prove measurements are correct or explain a physical loss.</span></div>
      <div class="metric-grid">${metric('Ledgers consistent',summ.lots_consistent||0,`${summ.lots_checked||0} material lots checked`,'check')}${metric('Ledger mismatches',summ.lots_require_review||0,'Inventory differs from event history','alert','red')}${metric('Unresolved differences',summ.unresolved_discrepancies||0,'Measured transfers still under review','truck','amber')}${metric('Approved adjustments',kg(summ.approved_adjustments_kg||0),'Explicit controller-approved entries','clipboard','amber')}</div>
      <section class="panel"><div class="panel-head"><div><h2>Batch balance report</h2><p>Original material = current recorded stock + approved accounting adjustments</p></div>${searchBar('Search a batch or location')}</div>
      <div class="table-wrap"><table>${tableHeads(['Lot','Original receipt','Current recorded stock','Approved adjustments','Ledger status','Details'])}<tbody id="records-body">${rows.map(r=>`<tr data-search="${esc([r.lot_no,r.status].join(' ').toLowerCase())}"><td><strong>${esc(r.lot_no)}</strong></td><td class="numeric">${kg(r.original_received_kg)}</td><td class="numeric">${kg(r.current_stock_kg)}</td><td class="numeric">${kg(r.approved_adjustments_kg)}</td><td>${pill(r.status)}</td><td><button class="btn tiny secondary" data-recon-lot="${esc(r.lot_id)}">Inspect balance</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-state">No material lots have been recorded.</div>'}<div class="no-results" id="no-results" hidden>No matching lots.</div></section>
      <section class="panel"><div class="panel-head"><div><h2>Transfer measurements</h2><p>Separate departure and arrival weights, with no guessed explanations.</p></div></div>
      <div class="table-wrap"><table>${tableHeads(['Transfer','Dispatched','Received','Difference','Finding'])}<tbody>${movements.map(t=>`<tr><td><strong>${esc(t.transfer_no)}</strong></td><td class="numeric">${kg(t.dispatched_kg)}</td><td class="numeric">${kg(t.received_kg)}</td><td class="numeric">${t.difference_kg===null?'—':delta(t.difference_kg)}</td><td>${t.case_status==='CLOSED_ADJUSTED'?'Short receipt · accounting adjusted':esc(({MATCHED:'Recorded weights match',SHORT_RECEIPT:'Short receipt · investigate',OVER_RECEIPT:'Over receipt · investigate',AWAITING_RECEIPT:'Waiting for independent receipt',NOT_DISPATCHED:'Reservation only'})[t.stage]||t.stage)}</td></tr>`).join('')}</tbody></table></div>${movements.length?'':'<div class="empty-state">No transfers yet.</div>'}</section>`;
  }
  function activityView(){const items=state.data.audit||[];const names={TRANSIT_ADJUSTMENT_APPROVED:'Accounting adjustment approved',RECEIPT_SUBMITTED:'Delivery recorded',INSPECTION_RELEASED:'Material approved',INSPECTION_HELD:'Material held',INSPECTION_REJECTED:'Material rejected',TRANSFER_RESERVED:'Material reserved',TRANSFER_DISPATCHED:'Material dispatched',TRANSFER_RECEIVED:'Material received',INVESTIGATION_STARTED:'Investigation started'};return `${pageHeading('Activity history','See who performed an operation and when. Original transactions are preserved.')}
    <section class="panel"><div class="panel-head"><div><h2>Latest recorded actions</h2><p>Read-only audit history from the backend</p></div>${searchBar('Search action or operator')}</div><div class="activity-list" id="records-body">${items.map(item=>`<div class="activity-row" data-search="${esc([item.action,item.actor_name].join(' ').toLowerCase())}"><div class="activity-icon">${ico(item.action.includes('INSPECTION')?'shield':item.action.includes('TRANSFER')?'truck':'clipboard',19)}</div><div><strong>${esc(names[item.action]||item.action.replaceAll('_',' ').toLowerCase())}</strong><small>${esc(item.actor_name||'Unknown user')} · ${esc(item.entity)}</small></div><time>${friendlyDate(item.time)}</time></div>`).join('')}</div>${items.length?'':'<div class="empty-state">No actions recorded yet.</div>'}<div class="no-results" id="no-results" hidden>No matching activity found.</div></section>`;}
  function actionModal({title,description,fields,submitText,onSubmit}){
    const overlay=document.createElement('div');overlay.className='modal-overlay';
    overlay.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(description)}</p></div><button type="button" class="dialog-close" aria-label="Close dialog">${ico('close',19)}</button></header><form class="dialog-body">${fields.map(f=>`<div class="form-field"><label for="dlg-${esc(f.id)}">${esc(f.label)}</label>${f.type==='textarea'?`<textarea id="dlg-${esc(f.id)}" name="${esc(f.id)}" rows="4" minlength="${f.minlength||2}" required placeholder="${esc(f.placeholder||'')}"></textarea>`:`<input id="dlg-${esc(f.id)}" name="${esc(f.id)}" type="${esc(f.type||'text')}" ${f.min!=null?`min="${esc(f.min)}"`:''} ${f.max!=null?`max="${esc(f.max)}"`:''} ${f.step!=null?`step="${esc(f.step)}"`:''} ${f.minlength?`minlength="${esc(f.minlength)}"`:''} required placeholder="${esc(f.placeholder||'')}"/>`}${f.hint?`<span class="field-hint">${esc(f.hint)}</span>`:''}</div>`).join('')}<footer class="dialog-foot"><button type="button" class="btn secondary" data-cancel>Cancel</button><button type="submit" class="btn primary">${esc(submitText)} ${ico('arrow',16)}</button></footer></form></section>`;
    root.append(overlay);const oldFocus=document.activeElement;const close=()=>{document.removeEventListener('keydown',onKey);overlay.remove();if(oldFocus?.isConnected)oldFocus.focus();};const onKey=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const foc=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled])')];if(!foc.length)return;const first=foc[0],last=foc.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',onKey);
    overlay.querySelector('.dialog-close').onclick=close;overlay.querySelector('[data-cancel]').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.querySelector('form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));close();onSubmit(v);};overlay.querySelector('input,textarea,.dialog-close')?.focus();
  }
  function readModal(title,content){const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<section class="dialog read-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>Read-only information from the shared database</p></div><button type="button" class="dialog-close" aria-label="Close dialog">${ico('close',19)}</button></header><div class="dialog-body">${content}<footer class="dialog-foot"><button class="btn secondary" id="read-close">Close</button></footer></div></section>`;root.append(overlay);const oldFocus=document.activeElement;const close=()=>{document.removeEventListener('keydown',escapeClose);overlay.remove();if(oldFocus?.isConnected)oldFocus.focus();};function escapeClose(e){if(e.key==='Escape')close();}document.addEventListener('keydown',escapeClose);overlay.querySelector('.dialog-close').onclick=close;overlay.querySelector('#read-close').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.querySelector('.dialog-close').focus();}
  const detail=(k,v)=>`<div class="detail-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`;
  function transferDetails(id){const t=(state.data.transfers||[]).find(x=>x.id===id);if(!t)return;const difference=t.difference_kg==null?'Not yet available':delta(t.difference_kg);readModal('Transfer '+t.transfer_no,`<div class="evidence-split"><div class="evidence-box"><small>SENDING DEPARTMENT</small><h3>${esc(t.source)}</h3><strong>${kg(t.dispatched_kg)}</strong><p>${esc(t.dispatch_reference||'Dispatch not confirmed')}</p></div><div class="evidence-box"><small>RECEIVING DEPARTMENT</small><h3>${esc(t.destination)}</h3><strong>${kg(t.received_kg)}</strong><p>${esc(t.receipt_reference||'Receipt not confirmed')}</p></div></div>${detail('Material lot',t.lot_no)}${detail('Quantity reserved',kg(t.reserved_kg))}${detail('Recorded difference',difference)}${detail('Transfer state',statuses[t.status]?.[0]||t.status)}<div class="explain-mini">${ico('info',16)} A difference alone does not establish why the two records disagree.</div>`);}
  async function traceLot(id){try{const l=await api(`/api/lots/${encodeURIComponent(id)}/history`);const stock=l.stocks.map(s=>detail(s.location,`${kg(s.on_hand_kg)} on hand · ${kg(s.reserved_kg)} reserved`)).join('');const entries=l.timeline.map(e=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${esc(e.event)}</strong><small>${friendlyDate(e.time)} · ${esc(e.reference)}</small><p>${esc(e.detail)}</p></div></div>`).join('');readModal('Material history · '+l.lot_no,`<div class="lot-intro"><strong>${esc(l.material)}</strong><span>Originally received from ${esc(l.supplier)}</span><b>${kg(l.origin_weight_kg)}</b></div><h3 class="modal-subheading">Where this material is now</h3>${stock||'<p>No stock rows found.</p>'}<h3 class="modal-subheading">Recorded journey</h3><div class="timeline">${entries}</div>`);}catch(err){state.error=err.message;render();}}
  async function act(path,method,body,success){try{await api(path,method,body);state.notice=success;state.error='';await load();}catch(err){state.error=err.message;state.notice='';render();}}
  function exportSummary(){const data=state.data;const lines=[['SteelFlow controller summary','Training data'],['As of',new Date().toISOString()],['Yard on hand kg',data.dashboard?.yard_on_hand_kg],['In-transit balance kg',data.dashboard?.transit_balance_kg],['Receipts awaiting approval',data.dashboard?.receipts_pending],['Transfers awaiting receipt',data.dashboard?.transfers_in_transit],['Open discrepancies',data.dashboard?.open_discrepancies],[],['Transfer','Lot','Dispatched kg','Received kg','Difference kg','Status'],...(data.transfers||[]).map(t=>[t.transfer_no,t.lot_no,t.dispatched_kg??'',t.received_kg??'',t.difference_kg??'',t.status])];const cell=s=>{let v=String(s??'');if(/^[=+@-]/.test(v))v="'"+v;return `"${v.replaceAll('"','""')}"`;};const csv=lines.map(x=>x.map(cell).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='SteelFlow_Operations_Summary.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function applySearch(){const input=document.getElementById('table-search'),value=(input?.value||'').trim().toLowerCase();let shown=0;document.querySelectorAll('#records-body [data-search]').forEach(el=>{const s=el.dataset.status||'';const matchStatus=state.page!=='transfers'||state.filter==='all'||(state.filter==='reserved'&&s==='RESERVED')||(state.filter==='transit'&&s==='DISPATCHED')||(state.filter==='difference'&&s==='RECEIVED_WITH_DIFFERENCE')||(state.filter==='done'&&s.startsWith('RECEIVED_'));const matchText=(el.dataset.search||'').includes(value);const visible=matchStatus&&matchText;el.hidden=!visible;shown+=visible?1:0;});const empty=document.getElementById('no-results');if(empty)empty.hidden=shown>0;}
  function attach(){
    root.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));
    root.querySelectorAll('[data-factory-filter]').forEach(el=>el.onclick=()=>{state.factoryFilter=el.dataset.factoryFilter;render();});
    root.querySelector('#export-summary')?.addEventListener('click',exportSummary);
    const q=root.querySelector('#table-search');if(q)q.addEventListener('input',applySearch);
    root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;root.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});applySearch();});
    if(state.page==='transfers')applySearch();
    const form=root.querySelector('#receipt-form');if(form){const gross=form.querySelector('#gross_kg'),tare=form.querySelector('#tare_kg'),weight=form.querySelector('#net-display'),err=form.querySelector('#weight-error'),submit=form.querySelector('[type=submit]');const update=()=>{const a=Number(gross.value),b=Number(tare.value);const entered=gross.value!==''&&tare.value!=='';const valid=entered&&a>b&&b>=0;weight.textContent=valid?kg(a-b):'—';err.hidden=!(entered&&!valid);submit.disabled=entered&&!valid;};gross.oninput=update;tare.oninput=update;form.onsubmit=e=>{e.preventDefault();const body=Object.fromEntries(new FormData(form));act('/api/receipts','POST',body,'Delivery saved. The supervisor can now inspect it.');};}
    root.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const decision=b.dataset.decision;actionModal({title:decision==='RELEASED'?'Approve material':decision==='HELD'?'Place delivery on hold':'Reject delivery',description:decision==='RELEASED'?'Approved weight will become available yard stock.':'Record a clear explanation so other operators understand the decision.',fields:[{id:'reason',label:'Inspection decision / reason',type:'textarea',minlength:3,placeholder:'Describe the inspection outcome'}],submitText:'Save inspection decision',onSubmit:v=>act(`/api/receipts/${encodeURIComponent(b.dataset.review)}/review`,'POST',{decision,reason:v.reason},decision==='RELEASED'?'Material approved and added to inventory.':'Inspection decision recorded.')});});
    root.querySelectorAll('[data-reserve]').forEach(b=>b.onclick=()=>actionModal({title:'Prepare transfer to Melting',description:`Available stock: ${kg(b.dataset.available)}. First reserve the quantity; confirm physical dispatch afterwards.`,fields:[{id:'quantity_kg',label:'Quantity to reserve (kg)',type:'number',min:0.001,max:b.dataset.available,step:0.001,placeholder:'Enter quantity in kg'}],submitText:'Reserve material',onSubmit:v=>act('/api/transfers','POST',{lot_id:b.dataset.reserve,quantity_kg:v.quantity_kg},'Material reserved. Open Transfers to confirm dispatch.') }));
    root.querySelectorAll('[data-dispatch]').forEach(b=>{
      const t=(state.data.transfers||[]).find(x=>x.id===b.dataset.dispatch);
      b.onclick=()=>actionModal({title:'Confirm weighed material departure',description:`You reserved ${kg(t?.reserved_kg)}. Enter the actual weight leaving the yard (not more than reserved). Any remainder stays available in the yard.`,fields:[{id:'measured_kg',label:'Measured weight leaving (kg)',type:'number',min:0.001,max:t?.reserved_kg,step:0.001,placeholder:'Actual dispatched weight'},{id:'evidence_reference',label:'Dispatch ticket / document reference',minlength:2,placeholder:'e.g. WB-OUT-105'}],submitText:'Confirm dispatch',onSubmit:v=>act(`/api/transfers/${encodeURIComponent(b.dataset.dispatch)}/dispatch`,'POST',v,'Measured dispatch saved. The receiving department can now acknowledge it.')});
    });
    root.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>actionModal({title:'Confirm material received',description:`The sender recorded ${kg(b.dataset.sent)}. Enter your independently observed receipt weight.`,fields:[{id:'received_kg',label:'Actual received weight (kg)',type:'number',min:0,step:0.001,placeholder:'Independent measured weight'},{id:'evidence_reference',label:'Receiving ticket / document reference',minlength:2,placeholder:'e.g. WB-IN-105'}],submitText:'Save received weight',onSubmit:v=>act(`/api/transfers/${encodeURIComponent(b.dataset.confirm)}/receive`,'POST',v,'Receiving measurement saved. Any difference is visible to the controller.')}));
    root.querySelectorAll('[data-investigate]').forEach(b=>b.onclick=()=>actionModal({title:'Start an investigation',description:'State what records or measurements must be checked. Do not claim a root cause without evidence.',fields:[{id:'note',label:'What will you investigate?',type:'textarea',minlength:10,placeholder:'Compare both weighbridge tickets; confirm calibration and transfer timing.'}],submitText:'Save investigation',onSubmit:v=>act(`/api/discrepancies/${encodeURIComponent(b.dataset.investigate)}/investigate`,'POST',v,'Investigation started. No material quantities were changed.')}));
    root.querySelectorAll('[data-close-shortage]').forEach(b=>b.onclick=()=>actionModal({title:'Approve an accounting adjustment',description:`This will clear ${kg(b.dataset.amount)} of unresolved transit stock. It is an accounting decision, NOT proof of physical loss. An authorized controller must retain evidence.`,fields:[{id:'evidence_reference',label:'Approved evidence reference',minlength:4,placeholder:'Approval or case document ID'},{id:'reason',label:'Approval reason and investigation outcome',type:'textarea',minlength:20,placeholder:'Explain what was checked and why the accounting adjustment is authorized'}],submitText:'Approve accounting adjustment',onSubmit:v=>act(`/api/discrepancies/${encodeURIComponent(b.dataset.closeShortage)}/close-shortage`,'POST',{...v,confirm_accounting_adjustment:true},'Accounting adjustment recorded with an audit trail. This does not establish physical loss.')}));
    root.querySelectorAll('[data-recon-lot]').forEach(b=>b.onclick=()=>{const r=(state.data.reconciliation?.lots||[]).find(x=>x.lot_id===b.dataset.reconLot);if(!r)return;readModal('Balance for '+r.lot_no,`${detail('Original recorded receipt',kg(r.original_received_kg))}${detail('Current recorded stock',kg(r.current_stock_kg))}${detail('Approved adjustments',kg(r.approved_adjustments_kg))}${detail('Consumed in manufacturing',kg(r.consumed_in_production_kg||0))}${detail('Unexplained accounting difference',kg(r.unexplained_accounting_difference_kg))}<h3 class="modal-subheading">Stock compared with ledger</h3>${r.locations.map(x=>`<div class="detail-row"><span>${esc(x.location)}</span><strong>${kg(x.on_hand_kg)} ${x.matches?'✓':'⚠'}</strong></div>`).join('')}<div class="explain-mini">${ico('info',16)} Matching records do not confirm the physical measurement was correct.</div>`);});
    root.querySelectorAll('[data-lot]').forEach(b=>b.onclick=()=>traceLot(b.dataset.lot));
    root.querySelectorAll('[data-transfer-details]').forEach(b=>b.onclick=()=>transferDetails(b.dataset.transferDetails));
    root.querySelectorAll('[data-view-transfer-id]').forEach(b=>b.onclick=()=>transferDetails(b.dataset.viewTransferId));
    attachProduction();
  }
  loginView();
})();
